<script>document.addEventListener('DOMContentLoaded',()=>{const f=document.getElementById('creditForm'),k=f.elements.kind;const sync=()=>{for(const [id,visible] of [['creditPayer',k.value==='deposit'],['creditAccount',k.value!=='use'],['creditCharge',k.value==='use']]){const box=document.getElementById(id);box.hidden=!visible;box.querySelectorAll('input,select').forEach(e=>{e.disabled=!visible;if(e.name==='team_party_kind'||e.name==='charge_id')e.required=visible;});}if(k.value==='deposit')document.getElementById('teamPartyKind').dispatchEvent(new Event('change'));};k.addEventListener('change',sync);sync();});</script>
